from datetime import date, timedelta

class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_date, points)
        self._pending = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")
        points = int(amount // 10)
        if points > 0:
            available = day + timedelta(days=14)
            self._pending.setdefault(customer, []).append((available, points))
        return points

    def _available_points(self, customer: str, day: date) -> int:
        entries = self._pending.get(customer, [])
        return sum(pts for avail, pts in entries if avail <= day)

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        return self._available_points(customer, day)

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0 or points % 100 != 0:
            raise ValueError("Points must be redeemed in multiples of 100")
        if points > self._available_points(customer, day):
            raise ValueError("Insufficient points balance")
        # Deduct from oldest available entries first (FIFO)
        remaining = points
        entries = self._pending.get(customer, [])
        for i, (avail, pts) in enumerate(entries):
            if remaining <= 0:
                break
            if avail <= day and pts > 0:
                used = min(pts, remaining)
                entries[i] = (avail, pts - used)
                remaining -= used
        self._pending[customer] = entries

    def customers(self) -> list[str]:
        """Return all customers, sorted."""
        return sorted(self._pending.keys())
```

